// Python repr() formatting for the value model used by this project.
// Value model: int -> BigInt, float -> Number, str -> String,
// bool -> Boolean, None -> null, list/tuple -> Array.

export function reprFloat(x) {
  if (Number.isNaN(x)) return 'nan';
  if (!Number.isFinite(x)) return x < 0 ? '-inf' : 'inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';
  const sign = x < 0 ? '-' : '';
  // toExponential() without an argument yields the shortest round-trip form.
  const [mant, expS] = Math.abs(x).toExponential().split('e');
  const exp = parseInt(expS, 10);
  const digits = mant.replace('.', '');
  // Python repr uses scientific notation when exp >= 16 or exp <= -5.
  if (exp >= 16 || exp <= -5) {
    let m = digits[0];
    if (digits.length > 1) m += '.' + digits.slice(1);
    const e = Math.abs(exp).toString().padStart(2, '0');
    return `${sign}${m}e${exp < 0 ? '-' : '+'}${e}`;
  }
  const decpt = exp + 1; // position of the decimal point relative to digits
  let out;
  if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    out = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return sign + out;
}

export function reprStr(s) {
  // Python prefers single quotes, switching to double quotes only when the
  // string contains a single quote but no double quote.
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

export function pyRepr(value) {
  if (value === null) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') return reprFloat(value);
  if (typeof value === 'string') return reprStr(value);
  if (Array.isArray(value)) return '[' + value.map(pyRepr).join(', ') + ']';
  throw new TypeError(`unsupported value for repr: ${String(value)}`);
}

