// Minimal parser for Python literals as accepted by eval() in the source
// script: lists, tuples, strings, ints (arbitrary precision -> BigInt),
// floats (-> Number), True / False / None.

class LiteralParser {
  constructor(text) {
    this.text = text;
    this.pos = 0;
  }

  error(msg) {
    throw new SyntaxError(`${msg} at position ${this.pos}`);
  }

  skipWs() {
    while (this.pos < this.text.length && /\s/.test(this.text[this.pos])) this.pos++;
  }

  peek() {
    this.skipWs();
    return this.text[this.pos];
  }

  expect(ch) {
    if (this.peek() !== ch) this.error(`expected '${ch}'`);
    this.pos++;
  }

  parse() {
    const value = this.parseValue();
    this.skipWs();
    if (this.pos !== this.text.length) this.error('unexpected trailing characters');
    return value;
  }

  parseValue() {
    const ch = this.peek();
    if (ch === undefined) this.error('unexpected end of input');
    if (ch === '[') return this.parseSequence('[', ']');
    if (ch === '(') return this.parseSequence('(', ')');
    if (ch === "'" || ch === '"') return this.parseString();
    if (this.text.startsWith('True', this.pos)) { this.pos += 4; return true; }
    if (this.text.startsWith('False', this.pos)) { this.pos += 5; return false; }
    if (this.text.startsWith('None', this.pos)) { this.pos += 4; return null; }
    return this.parseNumber();
  }

  parseSequence(open, close) {
    this.expect(open);
    const items = [];
    if (this.peek() === close) { this.pos++; return items; }
    for (;;) {
      items.push(this.parseValue());
      const next = this.peek();
      if (next === ',') { this.pos++; continue; }
      if (next === close) { this.pos++; return items; }
      this.error(`expected ',' or '${close}'`);
    }
  }

  parseString() {
    const quote = this.text[this.pos++];
    let out = '';
    for (;;) {
      if (this.pos >= this.text.length) this.error('unterminated string');
      const ch = this.text[this.pos++];
      if (ch === quote) return out;
      if (ch !== '\\') { out += ch; continue; }
      if (this.pos >= this.text.length) this.error('unterminated escape');
      const esc = this.text[this.pos++];
      switch (esc) {
        case 'n': out += '\n'; break;
        case 't': out += '\t'; break;
        case 'r': out += '\r'; break;
        case '\\': out += '\\'; break;
        case "'": out += "'"; break;
        case '"': out += '"'; break;
        case '0': out += '\0'; break;
        case 'x': {
          const hex = this.text.substr(this.pos, 2);
          if (!/^[0-9a-fA-F]{2}$/.test(hex)) this.error('invalid \\x escape');
          out += String.fromCharCode(parseInt(hex, 16));
          this.pos += 2;
          break;
        }
        case 'u': {
          const hex = this.text.substr(this.pos, 4);
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.error('invalid \\u escape');
          out += String.fromCharCode(parseInt(hex, 16));
          this.pos += 4;
          break;
        }
        default: out += esc;
      }
    }
  }

  parseNumber() {
    const rest = this.text.slice(this.pos);
    const m = /^[+-]?(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)?/.exec(rest);
    if (!m) this.error('invalid literal');
    this.pos += m[0].length;
    const token = m[0];
    const isFloat = token.includes('.') || token.includes('e') || token.includes('E');
    if (isFloat) return parseFloat(token);
    return BigInt(token);
  }
}

export function parseLiteral(text) {
  return new LiteralParser(text).parse();
}

