// Reimplementation of the boltons.iterutils helpers used by the source
// script, matching their observed behavior.

// flatten: recursively yields the leaves of nested iterables (lists/tuples,
// both modeled as JS Arrays). Strings are treated as scalars, not iterables.
export function* flatten(iterable) {
  for (const item of iterable) {
    if (Array.isArray(item)) yield* flatten(item);
    else yield item;
  }
}

// chunked: yields Arrays of length `size`; the final chunk may be shorter.
// An empty input yields no chunks.
export function* chunked(iterable, size) {
  let chunk = [];
  for (const item of iterable) {
    chunk.push(item);
    if (chunk.length === size) {
      yield chunk;
      chunk = [];
    }
  }
  if (chunk.length > 0) yield chunk;
}

