// Python `*` operator semantics for `x * 2` as used by the source script.

export function pyMulByInt(x, n) {
  if (typeof x === 'bigint') return x * n; // int * int -> int
  if (typeof x === 'number') return x * Number(n); // float * int -> float
  if (typeof x === 'boolean') return BigInt(Number(x)) * n; // True * 2 -> 2
  if (typeof x === 'string') return x.repeat(Number(n)); // 'ab' * 2 -> 'abab'
  throw new TypeError(
    `unsupported operand type(s) for *: '${pyTypeName(x)}' and 'int'`,
  );
}

function pyTypeName(x) {
  if (x === null) return 'NoneType';
  if (Array.isArray(x)) return 'list';
  return typeof x;
}

