// Minimal stand-in for the argparse configuration of the source script:
//   parser.add_argument('--a', type=str, required=True, help='Nested list structure')
// Replicates argparse's usage/error/help text, exit codes, and the
// `--a value` / `--a=value` forms. No external dependencies.

import { basename } from 'node:path';

const PROG = basename(process.argv[1] || 'test11.mjs');

const USAGE = `usage: ${PROG} [-h] --a A`;

const HELP = `${USAGE}

options:
  -h, --help  show this help message and exit
  --a A       Nested list structure
`;

function fail(message) {
  process.stderr.write(`${USAGE}\n${PROG}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv = process.argv.slice(2)) {
  let a;
  const extras = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      process.stdout.write(HELP + '\n');
      process.exit(0);
    } else if (arg === '--a') {
      if (i + 1 >= argv.length) fail('argument --a: expected one argument');
      a = argv[++i];
    } else if (arg.startsWith('--a=')) {
      a = arg.slice('--a='.length);
    } else {
      extras.push(arg);
    }
  }
  if (extras.length > 0) fail(`unrecognized arguments: ${extras.join(' ')}`);
  if (a === undefined) fail('the following arguments are required: --a');
  return { a };
}

