import { parseLiteral } from './lib/pyliteral.mjs';
import { flatten, chunked } from './lib/iterutils.mjs';
import { pyMulByInt } from './lib/pyops.mjs';
import { pyRepr } from './lib/pyrepr.mjs';

const args = parseArgs();

const nested = parseLiteral(args.a);
const result1 = [...flatten(nested)]; // 展平嵌套列表
console.log(pyRepr(result1));
const result2 = [...chunked(result1, 2)]; // 对展平结果分块
